//   于是手坑被洗到顶、下回合又摸回来，等于这次② 白转了一圈。
// ============================================================================
// ★ 卡组总纲（用户 2026-10-24 口径，优先级高于下面所有具体判据）
//
//   升月的卡组逻辑是：与对方资源交换，再通过自身不断抽卡扩大场值和资源优势。
//   一切操作都要与对方互动才行。
//
//   落到代码上的四条判据（新写任何执行器先对照这四条）：
//   1) 每次操作都要与对方发生互动 —— 打断 / 弹回 / 无效 / 战破 / 夺取 / 削资源都算。
//      对空场自娱自乐的铺场、加速超量、贴 buff 一律降级或不动，
//      除非它是下一轮互动的必要铺垫（如群星先置顶，是为了对方回合那一次抽）。
//   2) 交换必须是赚的：我方付出的资源 < 对方损失的价值。白亏的 cost 一律不发 ——
//      效果已被无效（EffectNegated）、对方空场（Bounty 的 threat==0）、弹不到东西
//      （希耶娜/库露雪留手）、素材不足硬叠，都是这一条的具体实现。
//   3) 抽卡是唯一资源来源：能不花钱就抽，抽到即自跳，
//      用抽来的资源去换掉对方的资源 —— 把对局带进「对方越动、我方手牌越多」的正循环。
//   4) 手坑 / 无效只在能换到对方真实资源时交，不因为「手里有就发」，
//      也不为了「反正免费的」提前浪费掉时点。
//
//   判断一手划不划算，问一句：这一手在和对方换什么？换不到就别做。
// ============================================================================
// ★ v5.55（2026-10-25 用户口径，replay「墓地辉煌逻辑」17:12:10~26）：
//   「副葬堆的辉煌为啥不除外抽卡 … 记住除非你要把这个辉煌留在对方回合干扰，都是要主动除外抽卡，
//     而且这里 AI 犯了个错误，它场上发动的辉煌把墓地的辉煌洗回卡组了。」
//   三条规则，后面改这块先看这三条：
//   1) **墓地辉煌 ② 默认主动除外抽卡**。它是这副牌唯一的「不花钱抽 1」，
//      又是 ② 一回合只有 1 次的稀缺资源，绝不允许因为顺序闸门互相让位而整回合作废。
//      只有一种情况可以留着：明确要把它留到对方回合当「二速抽卡」干扰
//      （`SplendorFieldCanLandBounty` / `JellyfishHoldingTop` 这两个组合闸门）。
//   2) **场上辉煌 ① 的可选「洗回墓原本家」在 ② 没抽之前一律选「否」**（`OnSelectYesNo`）。
//      洗回卡组后 ② 的 `SetRange(LOCATION_GRAVE)` 就废了，等于白扔一次抽卡。
//   3) **副葬 ×2 同时在手不要互相死锁**：一张结算完就算「洗牌已发生」，
//      第二张不再参与顺序判断、本回合也不再发（`CanUseBurialNow` / `BurialActivate`）。
// ============================================================================
// ★ v5.56（2026-10-25 用户口径，replay「为什么不走斩杀路线换血」17:20:54~57）：
//   「AI 这里在斩杀回合为什么不走斩杀路线打战伤，明明对方空场。」
//   病根是**注册顺序**：`XyzBounty`（千金大奖）在 `IrisfilSummon`（黑智天至）之前，
//   GameAI 按顺序取第一个 true，所以只要场上凑得出第二对 7 星，它就再叠一只千金大奖，
//   斩杀线那几条执行器永远轮不到。那一局的实证：千金#1（**1400/2800，攻表只打 1400**）+ 大姐 2100，
//   翼 700 / 雅 1400 又被叠成千金#2 → 三拳只有 1400+1400+2100 = **4900**
//   （`GoToBattle` 当时打的是「对方空场」这条分支，不是「打点 ≥ 对方 LP」⇒ 4900 < 对方 LP）。
//   同素材走阶梯 = 千金#1 → 黑智天至 → 光子咆哮（战阶 5300）+ 翼 700 + 雅 1400 + 大姐 2100
//   = 9500，直接收人头；而且黑智天至 ① 让场上所有超量怪战阶 +阶级×100（千金若照叠 = 1400+700 = 2100）。
//   ⇒ 规则：**斩杀/抢血回合（`CanFinish()` || `RaceMode()`）且有可爬的千金基底 + 额外还有
//     黑智天至与光子咆哮时，第二对 7 星不叠千金大奖，让位给爬阶梯**（`LadderClimbReady`）。
//      不是斩杀回合时照旧叠千金（2800 的守备墙 + ② 弹卡）。
//
//   ★ v5.57 订正：v5.56 的伤害账把千金大奖的**守备力 2800** 当成打点了 ——
//     实际卡面 1400/2800，攻表三拳 = 1400+1400+2100 = 4900（不是 7700），阶梯 = 9500。
