//     西艾萝＞菈碧＞卡萝尔＞朔＞库露雪/希耶娜，并发动墓地群星效果只自己抽 1。
//     如果是升月后攻回合，如果自己能做出大姐，群星优先置顶
//     西艾萝＞库露雪/希耶娜＞菈碧＞卡萝尔＞朔，同样也是墓地效果自己只抽 1。
//     当然，如果自己做不出大姐，还是要先用掉双方抽 1 的效果。
//     群星置顶优先选择自己手牌场上没有的本家怪兽。」
//   实现：
//     · `_goingFirst` 在 `OnNewTurn` 里用「我方第一个回合是不是 T1」定先攻 / 后攻；
//     · `JackpotReachable()` = 已做出大姐 / 场上 ≥2 只 7 星 / 场上 1 只 + 手上有帐（② 返 1 卡自跳）；
//     · `PickStackFrom` 顶部加两套优先表 → 命中时 `PickFirstStack` 先挑「手牌 + 场上都没有」的；
//     · 置顶后这一次 ② **照常抽**（普通置顶不再置 `_comboTopHeld`，v5.70 的「留给对方回合」作废，
//       只有水母 combo 那一支保留）；有大姐选 ●2，做不出大姐就现在用 ●1。
// ============================================================================
// ★ v5.71（2026-10-26 用户口径，replay「_LastReplay.yrp」+ 截图）：
//   「加一个逻辑，墓地有群星，场上有未眠之城的时候，群星要把抽卡效果用掉，
//     而且这里应该是自己抽 1 的那个效果。」
//   病根：v5.40 / v5.70 给群星② 套的三层「留着更赚」的闸门，全都默认**这张卡会一直在墓地**——
//     · v4.4 `_holdMode`（水母停铺 → 抽到的本家跳不了，白弃）
//     · v5.40 `TopHeldForEnemyTurn`（群星① 置顶了菈碧/希耶娜/库露雪 → 留给对方回合大姐抽）
//     · v5.2  `HoldDrawForOrder`（手里有副葬 / 群星还没置顶 → 先让顺序发生）
//   但 `c72978038.lua` 的 e4（未眠 ③）在**自己·对方的结束阶段**把墓地·除外状态的
//   「盈彩月夜」卡全部洗回卡组（`SEQ_DECKSHUFFLE`）—— 城在场上，墓地这张群星就**留不过这个回合**。
//   ⇒ 城在场上 = 这张卡有死线（和辉煌 ② 的 v5.50 完全同一条）：所有「留着」的理由失效，
//     现在不用就是白扔一张。有大姐（魔法师族本家超量）时一律选 **●2「只自己抽 1」**，
//     ●1「双方各抽 1」等于给对面也送一张，只有凑不出 ●2 时才退回。
//   实现：`StarsBanish` 最前面加一条 `CityWillShuffleGrave() && HasSpellcasterXyz()` 的优先分支，
//   直接发 ●2，跳过上面三层闸门。
// ============================================================================
// ★ v5.70（2026-10-26 用户口径，三条一起）：
//   「墓地的群星增加一个逻辑，如果自己场上能做出大姐，则优先等做出大姐后开第二个效果抽 1
//     （而不是双方抽 1）。还有一种逻辑，升月先攻如果中了水母或者增殖的 G，叠了大姐后开效果
//     抽 1 如果抽到本家不跳下来，另外如果提前用群星置顶了本家怪兽（具有干扰效果的），
//     先不开效果抽卡，等对方回合对方有动作了再看情况抽卡。」
//   (1) **群星② 等大姐**：`c46983930.lua` 的 `s.drtg` 用 `aux.SelectFromOptions` 给了两个选项 ——
//       ●1「双方各抽 1」（`aux.Stringid(id,3)`，恒可用）与 ●2「自己抽 1」（`aux.Stringid(id,4)`，
//       要求场上有表侧魔法师族本家超量 = 大姐）。没有大姐时只能选 ●1，白送对面一张。
//       ⇒ 只要这回合还有路把大姐摆到 EX 区（`JackpotComingThisTurn`），就把这次发动压住；
//         M2 大姐落地后 `HasSpellcasterXyz()` 成立，下一次询问自然改选 ●2。
//       这是 v5.23 那条「未眠② 等大姐再发 ●2 白抽」的同一口径，只是对象换成墓地群星。
//   (2) **抽到本家不跳（G 也挡）**：`DiscardOrBounce` 的旧闸门是
//       `(_holdMode || (_jellyfishBoardSet && _jellyfish))` —— 中水母时能挡，中**增殖的 G** 时
//       `_jellyfish` 为 false → 希耶娜/库露雪的「① 抽到自跳」照跳。但 G 罚的是**一切特招**，
//       这一跳等于白送对面一张。现在按 desc 把 ①（抽到自跳 = 特招）与 ③（丢弃自身抽 1 = 不是特招）
//       分开：① 走 `_jellyfishFreeze`（水母 / G 都挡），③ 只在 `_holdMode`（整回合不做动作）时压住。
//   (3) **置顶了干扰本家就别抽**：v5.40 只在水母 combo（`_jellyfishCombo`）时压住本回合的抽卡，
//       把牌堆顶那张留给对方回合大姐抽 1。用户口径把这条泛化：只要群星① 置顶的是
//       **菈碧 / 希耶娜 / 库露雪**（对方回合加速超量 / 弹怪 / 弹魔陷），本回合的抽卡就全部让位 ——
//       它们抽到手里本回合也跳不了（跳下来还白喂 G/水母），留在牌堆顶反而能在对方回合
//       「有动作时」被大姐抽出来、落地即干扰。
//       西艾萝（持续抽卡源）与卡萝尔（抽到即再抽 1）不在此列：本回合抽上来就是实打实的收益。
// ============================================================================
// ★ v5.62（2026-10-26 用户口径，replay「2026-10-26 01-23-28 优化.yrp」+ 同型截图）：
//   「AI 在能进行战斗阶段的回合，升月方只有两只 7 星的情况，很明显攻击力两只 7 星的战斗伤害
//     要大于大姐的战斗伤害，正确操作是两只 7 星战斗后主要阶段 2 守备表示特殊召唤大姐。」
//   病根：`XyzJackpot` 从来没有阶段闸门 —— 主阶 1 一看到 2 只 7 星就立刻叠大姐。
//     shengyue.log 01:23:52 的实证：场上 2 只 2100/2100（对方空场），两拳 4200 的战斗伤害
//     当场缩水成大姐的一拳 2100，而且叠完还「抢血模式 → 大姐 攻击表示」去打。
//     主阶 1 就把素材换成 2100 的单拳，等于白扔一半伤害 —— M2 明明还有一次「打完再叠」的机会。
//   ⇒ 规则：
//     1) **主阶 1 / 我方回合 / 对方空场**时先算账（`JackpotWaitForBattle`）：
//        两只素材的攻击力合计 > 大姐 2100 → 本回合不叠，两只 7 星先打进战阶，叠大姐推给**主阶 2**；
//        合计 ≤ 2100（两只 700 那种）→ 照旧主阶 1 叠，单拳 2100 反而更大。
//     2) 对方场上有怪时不参与这条（可能撞墙，伤害算不准），仍走原来的判断。
//     3) **主阶 2 叠出来的大姐一律守备表示**（`OnSelectPosition`）：这一回合已经没有攻击机会，
//        站着只是给对面当靶子，横着才是「2100 的墙 + EX 区全抗 + 检索置换」。
// ============================================================================
// ★ v5.69（2026-10-26 用户口径，replay「2026-10-26 14-06-07.yrp」）：
//   「升月方这里两只 7 星手牌一张卡萝尔，正确操作应该是将手牌的卡萝尔**不做解放召唤**并发动
//     效果抽卡，场上的 3 只 7 星进战斗阶段抢血，然后主要阶段 2 希耶娜和卡萝尔叠放大姐（守备表示）。」
//   两处病根：
//   (1) **卡萝尔被「撤销召唤」而不是「不解放召唤」**。v5.67 只在 `OnSelectTribute` 里回空列表，
//       撤销的是整次召唤 —— 她既没上场、也没抽到那 1 张。真正的开关在更前面：
//       `c11333460.lua` 的 e2 是 `EFFECT_SUMMON_PROC`，能用「不解放召唤」时引擎会先发
//       **MSG_SELECT_OPTION**（选项 desc = `aux.Stringid(id,1)` = id*16+1），而 WindBot 原来的
//       `Executor.OnSelectOption` 恒返回 -1 → `GameAI` 兜底取 **0** = 列表第一项 = 解放召唤。
//       ⇒ 新增 `OnSelectOption` 覆写：这次询问里主动挑 desc=id*16+1 那一项。
//   (2) **主阶 1 千金大奖抢走素材**。`XyzJackpot`（一掷乾坤 / 大姐）从 v5.62 起会「先不叠，打完
//       再叠」，但 `XyzBounty`（千金大奖）没有这道闸门，它紧接着把两只 7 星叠掉 ——
//       日志 14:06:10.554 / 10.560 实证：刚写完「一掷乾坤主阶 1 先不叠」，下一行就 `超量 千金大奖`。
//       三拳（希耶娜 2800 / 帐 2100 / 卡萝尔 700）当场缩成千金一拳。
//       ⇒ `XyzBounty` 共用 `JackpotWaitForBattle` 的算账，M1 同样推迟到 M2。
//   连带效果：M2 叠出的是 EX 区的大姐（魔法师族）→ 未眠之城 ② 走 ●2「白抽 1」而不是 ●1
//   「洗一张手牌再抽」。
// ★ v5.68（2026-10-26 用户口径）：「千金大奖有素材，有时自己或者对方怪兽从手卡特殊召唤
//   会不触发千金大奖取素材弹卡。」
//   病根不在协议/触发，而在 `BountyActivate()` 自己答「不发」：
//   · v5.16 的「抢血模式保留基底」（`RaceMode()`）—— 日志实测拦掉 97 次；
//   · v5.48 的「对方怪 ≤1 且能斩杀就留着」—— 又拦掉 30 次。
//   两条都建立在同一个假设上：发过效果 `_bountyActivated` 就打上 flag，黑智天至的 ovfilter
//   要求基底「本回合没在怪兽区发过效果」→ 斩杀线断。但弹卡是**回卡组最下面**（对方收不回来），
//   1 个素材换 1 张永久解，比留一个可能打不进去的 5300 更值 —— 用户已经明确要发。
//   现在不留任何例外：只要还有素材、对方场上还有卡，就发。
// ★ v5.63（2026-10-26 用户口径，截图：我方 光子咆哮 8300 + 大姐 2100，对方前场只剩盖卡）：
//   「优化战斗逻辑，对方场上若只有盖卡，先用攻击力低的怪兽（一般是大姐）试探，
//     再让高攻怪兽攻击。」
//   盖卡里可能是「攻击宣言时破坏 / 除外攻击者」的陷阱（幽闭 / 炸裂装甲那类），
//   也可能是翻过来就炸场的盖怪。先拿不值钱的那只（大姐 2100）去踩，
//   踩完高攻打点再打脸 —— 反过来先派 8300，等于把整回合最大的打点白送给一张盖牌。
//   落地（`OnSelectAttacker`，两条路径走法不同，不能并成一条）：
//     · **前场有盖怪**（`defenders` 非空）：引擎按攻击力从高到低排、从 list[0] 往后试，
//       会先派大哥去撞 → 这里必须把最弱的那只提到 list[0]。
//     · **前场全空、只有后场盖牌**：`GameAI.OnSelectBattleCmd` 的直击分支取的是 list **末尾**
//       （＝最弱的那只），本来就是低攻先上 → 这里**不能重排**，重排反而会把 8300 顶到末尾。
//   与 v5.31 的诱饵（连接栗子球）/ allWeak 不冲突：那两条要求对方有**表侧**怪，这条要求**没有**表侧怪。
