	private ClientCard _blazePrey;           // 要破坏的「对方」那张（场地 / 表侧永续优先）
	private int _blazePending;               // 还剩几次选卡要接管：2 = 自己的，1 = 对方的
	// ★ v5.11：重铠光子龙 ② 要破坏的那张（对方场上表侧卡），发动时点名，选卡时照选。
	private ClientCard _armorTarget;
