	//   `Util.GetLastChainCard()` 在连锁结算完就空了，而锁鸟这类**延迟诱发**（EFFECT_FLAG_DELAY）
	//   是在整条连锁结算完之后才问我们 —— 那时连锁已经清空，只能靠这里记的「最后一手是谁」。
	private int _lastChainController = -1;

